INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Frieren: Pháp Sư Tiễn Táng (Phần 2)', 'Frieren: Beyond Journey''s End (Season 2)', 'frieren-phap-su-tien-tang-phan-2', '<p>Sau một thập kỷ phiêu lưu, Frieren cùng tổ đội của dũng sĩ Himmel đã đánh bại Ma vương và mang lại hòa bình cho thế giới. Thế rồi cô ấy, một Elf với thọ mệnh hơn cả ngàn năm tuổi, lập lời hứa sẽ tái ngộ cùng nhóm Himmel rồi lên đường đi phiêu lưu một mình. 50 năm sau, Frieren đến thăm Himmel, nhưng lúc này anh ta đã già và chỉ còn lại một chút thời gian ngắn ngủi. Chứng kiến cái chết của Himmel, Frieren hối hận vì đã không "tìm hiểu nhiều hơn về con người", và thế là một chuyến phiêu lưu mới của cô với mục đích trên đã bắt đầu. Trên chuyến phiêu lưu này, cô đã gặp gỡ rất nhiều người và trải qua rất nhiều sự kiện.</p>', 'series', 'ongoing', 'FHD', 'Vietsub', 2026, 0, 'Tập 2', '10', 0, false, {'type': 'tv', 'id': '209867', 'season': 2, 'voteAverage': 8.732, 'voteCount': 632}, {'id': 'tt22248376', 'voteAverage': 8.9, 'voteCount': 60981}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Phù thủy kêu gọi', 'The Calling Witch', 'phu-thuy-keu-goi', '<p>Một anh trai và một em gái bị khủng bố bởi thứ dường như là tác phẩm văn học độc ác nhất của người mẹ quá cố của họ - Mụ Phù Thủy Gọi Hồn.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1475490', 'season': None, 'voteAverage': 6.25, 'voteCount': 4}, {'id': 'tt11609626', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Cá Voi Sát Thủ', 'Killer Whale', 'ca-voi-sat-thu', '<p>Hai người bạn thân Maddie và Trish rơi vào tình thế sinh tử khi bị mắc kẹt trong một đầm phá hẻo lánh, nơi trú ngụ của Ceto — một con cá voi sát thủ cực kỳ nguy hiểm. Không có đường thoát, họ buộc phải tìm cách sống sót trước kẻ săn mồi khổng lồ đang rình rập dưới làn nước.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1412598', 'season': None, 'voteAverage': 5.693, 'voteCount': 44}, {'id': 'tt33479805', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Tiên Đế Trở Về', 'Return Of The Immortal Emperor', 'tien-de-tro-ve', '<p>Thực lực vi tôn, nhưng khi không còn thực lực nào nữa thì tự nhiên mọi bi kịch cứ vậy mà ập đến, đó cũng là điều dĩ nhiên xảy đến khi mà con người ta không còn sức mạnh để khẳng định lời nói và sức mạnh nữa. Đó cũng là đôi nét sơ qua về câu chuyện Tiên Đế Trở Về, với anh chàng Vân Thanh Nham đầy thú vị. Xuất phát là một người dân hết sức bình thường, chẳng qua là mang trong mình một chút thiên phú mà đã vô tình bị cuốn đến thế giới khác gọi là Tiên Giới. Tại đó, Vân Thanh Nham trở thành một trong 10 vị Tiên Đế lừng danh, sống một cuộc sống an nhàn đến phát chán, thêm với những điều phiền muộn của nơi đây và nỗi nhớ nhà không nguôi, sau 3000 năm dài đằng đẵng thì anh đã quyết định quay trở lại nhân gian, tìm lại gia đình và người thân của mình. Nhưng trên đường xuyên không trở về, vô vàn gian khó cứ luôn xảy đến, rồi lại bị đuổi đánh dữ dội, những tu vi và thần khí của Vân Thanh Nham bỗng chốc trở về con số 0.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub + Thuyết Minh', 2025, 0, 'Tập 15', '16 Tập', 0, false, {'type': 'tv', 'id': '303881', 'season': 1, 'voteAverage': 10, 'voteCount': 1}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Huyền Giới Chi Môn', 'The Gate Of Mystical Realm', 'huyen-gioi-chi-mon', '<p>Huyền Giới Chi Môn, câu chuyện về hành trình từ một cậu thiếu niên tầm thường cho đến trở thành võ giả chân chính của Thạch Mục với những nốt thăng trầm đáng nhớ. Vốn xuất thân tầm thường, tầm thường đến mức chỉ là một con nuôi trong một thế gia, vậy nên Thạch Mục cũng bị phân biệt đối xử chẳng được ai coi trọng, việc tu luyện của cậu cũng vậy, chẳng có gì để trợ giúp như những người khác cả, phải tự thân vận động thôi. Bắt buộc phải trở thành võ giả, bởi chỉ có võ giả thì mới nhận được sự thừa nhận về năng lực cũng như sự kính trọng từ mọi người. Nhưng hành trình ấy của Thạch Mục cũng chẳng hề dễ dàng, gian nan và cũng không thiếu nguy hiểm. Từ những trận chiến thập tử nhất sinh, tưởng hẹo mười mươi, cho đến những ngày tháng bị rượt đuổi chạy như bị Tào Tháo rượt, những những khoảnh khắc ấy đã tôi luyện cho Thạch Mục ngày càng trưởng thành, trở thành một võ giả có thể cứu rỗi tương lai của muôn người.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 11', '26 Tập', 0, false, {'type': 'tv', 'id': '301429', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thu Hút Mãnh Liệt', 'Affinity', 'thu-hut-manh-liet', '<p>Năm năm trước, Ngô Nùng Vũ theo anh trai Ngô Tư Nguyên đến hiện trường một vụ án mạng, từ đó số phận cô giao thoa với nghi phạm Tạ Tân Tự. Dường như cơ thể cô tự nhiên tỏa ra sức hấp dẫn đặc biệt đối với anh, khiến anh vừa trông thấy cô đã nảy sinh khao khát mãnh liệt muốn chiếm hữu cô. Năm năm sau, để có được Ngô Nùng Vũ, Tạ Tân Tự ngụy trang thành một giáo sư y khoa lạnh lùng, âm mưu tiếp cận cô, cẩn thận giăng bẫy khiến cô yêu mình, hai người cùng dấn thân vào một cuộc phiêu lưu mạo hiểm. Trong những tháng ngày tiếp xúc với cô gái rạng rỡ như mặt trời, gã điên trời sinh thiếu sự đồng cảm dần dần học được cách nhận biết cảm xúc như người bình thường!</p><p>&nbsp;</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 24', '34 Tập', 0, false, {'type': 'tv', 'id': '311025', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thiếu Niên Ca Hành: Thiên Hạ Vô Song', 'The Blood of Youth: Quest of Heroic Hearts', 'thieu-nien-ca-hanh-thien-ha-vo-song', '<p>Câu chuyện theo chân Vị Quy – thiếu niên mất trí nhớ mang mối thù diệt môn – cùng Lôi Linh Trạch và Hoa Tiểu Hoa trên hành trình truy tìm Thiên Trảm Kiếm, đối đầu thế lực ma đạo Thiên Ngoại Thiên, qua đó khắc họa một giang hồ đầy biến động nơi tình bạn, niềm tin và tinh thần hiệp nghĩa quyết định ai mới là “đệ nhất thiên hạ”.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 10', '24 Tập', 0, false, {'type': 'tv', 'id': '312114', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thực Ra Không Phải Mối Tình Đầu', 'Predestined Love', 'thuc-ra-khong-phai-moi-tinh-dau', '<p>Sau khi trở về nhà để vực dậy nhà hàng đang trên bờ vực phá sản của mẹ, Ren Xizhou gặp lại người bạn học cũ thời trung học, Xiang Nanfeng. Cùng nhau nỗ lực cứu vãn nhà hàng và đối mặt với những hiểu lầm trong quá khứ, họ hàn gắn những vết thương cũ và tìm thấy dũng khí để bắt đầu một cuộc sống mới.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 20', '24 Tập', 0, false, {'type': 'tv', 'id': '295430', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('96 Phút Sinh Tử', '96 Minutes', '96-phut-sinh-tu', '<p>Ba năm sau thảm kịch tại trung tâm mua sắm, trên chuyến tàu cao tốc định mệnh, nữ cảnh sát Huỳnh Hân (Tống Vân Hoa) và chồng cô là cựu chuyên gia gỡ bom - Tống Khang Nhân (Lâm Bách Hoành), cùng đội trưởng Lý Kiệt (Lý Lý Nhân) bất ngờ nhận được tin nhắn thông báo một quả bom đã được cài sẵn trên tàu. Vụ việc lần này còn phức tạp hơn khi kẻ khủng bố dường tính toán vô cùng tinh vi. Khi thời gian cạn dần, Tống Khang Nhân buộc phải ngăn thảm kịch xảy ra bằng mọi giá, đồng thời đối mặt với những ám ảnh kinh hoàng từ vụ nổ năm xưa.</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1271895', 'season': None, 'voteAverage': 7, 'voteCount': 2}, {'id': 'tt34381460', 'voteAverage': 6.8, 'voteCount': 227}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Chú Thuật Hồi Chiến (Phần 3)', 'JUJUTSU KAISEN Season 3', 'chu-thuat-hoi-chien-phan-3', '<p>Vì một lý do kỳ lạ nào đó, Yuji Itadori, mặc dù với thể chất hoàn hảo nhưng anh lại đâm đầu vào tham gia CLB Huyền Bí. Tuy nhiên, họ đã sớm phát hiện ra là những câu chuyện huyền bí hoàn toàn có thật khi các thành viên trong CLB lần lượt bị tấn công! Trong khi đó, Megumi Fushiguro “bí ẩn” lại đang truy tìm một đối tượng bị nguyền rủa cấp đặc biệt và cuộc tìm kiếm này đã đưa nhóm bạn đến Itadori</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 5', '13', 0, false, {'type': 'tv', 'id': '95479', 'season': 3, 'voteAverage': 8.6, 'voteCount': 4077}, {'id': 'tt12343534', 'voteAverage': 8.5, 'voteCount': 171858}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Skyscraper Live', 'Skyscraper Live', 'skyscraper-live', '<p>Không có dây thừng. Không sợ hãi. Huyền thoại solo tự do Alex Honnold mạo hiểm tất cả trong cuộc đua trực tiếp đầy rủi ro khi leo lên một trong những tòa nhà chọc trời cao nhất thế giới ở Đài Bắc, Đài Loan.<br>&nbsp;</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1599090', 'season': None, 'voteAverage': 7.625, 'voteCount': 12}, {'id': 'tt38598912', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Chén Thánh Của Eris', 'The Holy Grail of Eris', 'chen-thanh-cua-eris', '<p>Giữa thế giới quý tộc đầy dối trá và tham vọng, gia tộc Grail là ngoại lệ hiếm hoi khi luôn tôn thờ sự thật và liêm chính, và Constance Grail cũng lớn lên với niềm tin ấy. Nhưng lý tưởng của cô sụp đổ khi bị vị hôn phu phản bội và vu oan, còn "công lý" thì hoàn toàn ngoảnh mặt làm ngơ. Trong khoảnh khắc tuyệt vọng, linh hồn của Scarlet Castiel - ác nữ khét tiếng từng bị xử tử - xuất hiện và nhập vào Constance để lật ngược tình thế. Scarlet bị kết tội ám sát công chúa mười năm trước, nhưng sự thật đằng sau đó là một âm mưu tinh vi nhằm hãm hại cô. Đổi lấy sự trợ giúp, Scarlet yêu cầu Constance cùng mình vạch trần sự thật và trả thù những kẻ đã đẩy cô vào cái chết oan nghiệt.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '12 Tập', 0, false, {'type': 'tv', 'id': '283891', 'season': 1, 'voteAverage': 9, 'voteCount': 3}, {'id': 'tt38647635', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thành Phố Xa Xôi', 'Far Away', 'thanh-pho-xa-xoi', '<p>Một người phụ nữ và con trai mang theo thi thể của người chồng quá cố đến quê hương, quyết tâm chôn cất ông tử tế. Nhưng gia đình quyền lực của ông đã sớm mắc kẹt cô trong một mạng lưới bí mật và kiểm soát, khiến cô không thể trốn thoát.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2024, 0, 'Tập 31', '? Tập', 0, false, {'type': 'tv', 'id': '274556', 'season': 1, 'voteAverage': 7.5, 'voteCount': 12}, {'id': 'tt34063491', 'voteAverage': 7.1, 'voteCount': 2560}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Wonder Man', 'Wonder Man', 'wonder-man', '<p>Câu chuyện xoay quanh Simon Williams, một diễn viên đang chật vật tìm chỗ đứng tại Los Angeles. Simon sở hữu siêu năng lực (Năng lực ion - sức mạnh, tốc độ vượt trội, khả năng hồi phục…) nhưng phải giấu kín điều này vì tại Hollywood, các siêu anh hùng bị cấm tham gia ngành giải trí sau một sự cố thảm khốc trong quá khứ. Đột nhiên, anh có cơ hội thử vai trong một bộ phim siêu anh hùng remake mang tên Wonder Man, gặp gỡ và kết thân với Trevor Slattery (cây tấu hài quen thuộc của MCU, đóng vai trò người cố vấn "lắm chiêu" cho Simon), là diễn viên hết thời từng giả danh Mandarin trong Iron Man 3 và trở thành người dẫn dắt Simon bước vào giới showbiz hào nhoáng nhưng cũng đầy cạm bẫy.&nbsp;<br>Wonder Man khác với các siêu anh hùng đánh đấm hoành tráng thường thấy, đây là một bộ phim hành động - hài châm biếm đậm chất Hollywood, siêu anh hùng đóng phim siêu anh hùng, nhận được đánh giá cực cao từ giới chuyên môn. Cái hay của series này chính là việc Simon có năng lượng của một vị thần nhưng lại mang tâm hồn của một diễn viên nhạy cảm, cùng với sự kết hợp giữa Yahya (vai Simon Williams) và Ben Kingsley (vai Trevor Slattery) tạo nên một cặp bài trùng vô cùng thú vị, vừa hài hước vừa cảm động.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 3', '8 Tập', 0, false, {'type': 'tv', 'id': '198178', 'season': 1, 'voteAverage': 6.659, 'voteCount': 41}, {'id': 'tt21066182', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Bạn Thân Yêu Thương (Mùa 3)', 'Best Friends', 'ban-than-yeu-thuong-mua-3', '<p>Mười người đàn ông và phụ nữ độc thân bắt đầu chuyến đi homestay kéo dài 10 ngày. Trong suốt chuyến đi, họ sẽ xem xét lại mối quan hệ với bạn bè khác giới, tìm hiểu khả năng phát triển hơn nữa. Đồng thời, họ sẽ tiếp cận những người bạn mới quen với một tâm thế cởi mở, tìm hiểu lẫn nhau và xem liệu những tia lửa tình yêu khác nhau có thể được thắp lên hay không.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2023, 0, 'Tập 9', '10 Tập', 0, false, {'type': 'tv', 'id': '229043', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Transit Love (Phần 4)', 'EXchange (Season 4)', 'transit-love-phan-4', '<p>Các cặp đôi từng chia tay vì nhiều lý do khác nhau tụ họp lại để cùng nhìn lại tình yêu trong quá khứ và tìm kiếm tình yêu mới.</p>', 'series', 'completed', 'HD', 'Vietsub', 2025, 0, 'Hoàn tất (22/22)', '22 Tập', 0, false, {'type': 'tv', 'id': '128119', 'season': 4, 'voteAverage': 8.7, 'voteCount': 6}, {'id': 'tt28893202', 'voteAverage': 0, 'voteCount': 57}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Chúng Ta Ngang Tài Ngang Sức (Phần 2)', 'Live and Love (Season 2)', 'chung-ta-ngang-tai-ngang-suc-phan-2', '<p>Hai mươi chàng trai và cô gái hấp dẫn đang tìm kiếm tình yêu trên một hòn đảo hoang! Hai mươi người độc thân bắt đầu cuộc hành trình mười ngày để tìm kiếm tình yêu trong vùng hoang dã biệt lập. Dưới áp lực sinh tồn và những thử thách khắc nghiệt, họ sẽ bộc lộ thái độ cảm xúc chân thật nhất, đối mặt với sự lựa chọn tình yêu và thách thức sinh tồn. Trong vòng xoáy loại trừ và lựa chọn bạn đời liên tục, liệu họ có thể tìm thấy nửa kia của mình?</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '10 Tập', 0, false, {'type': 'tv', 'id': '254532', 'season': 2, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Xuyên Không Về 1995 Để Yêu Anh', 'Once More Love in 1995', 'xuyen-khong-ve-1995-de-yeu-anh', '<p>Sau chuyến du hành ngược thời gian về năm 1995, người phụ nữ hiện đại Zhuang Manying sử dụng những kỹ năng đương đại của mình để thay đổi số phận của mẹ, thăng tiến trong công việc và đối đầu với người yêu cũ lừa dối—nhưng lại bất ngờ vướng vào một mối tình phức tạp với người chú lạnh lùng, xa cách của mình.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 1, 'Tập 8', '24 Tập', 0, false, 0, 0, '2026-02-04T20:17:28.301');
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Độc Nhất Vô Nhị', 'The One', 'doc-nhat-vo-nhi', '<p>Cô gái 17 tuổi Dụ Duyên sống với cha, mẹ và anh trai tại một quán ăn do tổ tiên họ gây dựng. Là người duy nhất có thể nghe được trong một gia đình khiếm thính, cô đã lang thang giữa thế giới im lặng của gia đình và thế giới âm thanh bên ngoài kể từ khi còn nhỏ, và đã quen với vai trò là cầu nối và phiên dịch. Tình yêu thương và sự phụ thuộc của gia đình quấn chặt lấy cô như dây leo, nhưng ngọn lửa khao khát được nhìn thấy thế giới rộng lớn hơn cũng đang bùng cháy trong tim cô. Sự thay đổi đột ngột buộc Dụ Duyên phải đối mặt với tình thế tiến thoái lưỡng nan giữa việc theo đuổi ước mơ và bảo vệ gia đình. Trong những lựa chọn khi lớn lên, cô bé cố gắng tìm kiếm chính mình và những bài hát mà cô có thể chia sẻ với gia đình.<br>&nbsp;</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1366558', 'season': None, 'voteAverage': 6, 'voteCount': 5}, {'id': 'tt33294144', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Ella McCay', 'Ella McCay', 'ella-mccay', '<p>Một nữ chính trị gia trẻ đầy lý tưởng phải xoay xở giữa áp lực công việc và những rắc rối trong gia đình, trong khi chuẩn bị đảm nhận vị trí thống đốc bang thay cho người cố vấn lâu năm của mình — một biểu tượng chính trị kỳ cựu.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1206008', 'season': None, 'voteAverage': 5.406, 'voteCount': 32}, {'id': 'tt30096221', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Dựng Lại Cuộc Đời', 'Rebuilding', 'dung-lai-cuoc-doi', '<p>Sau khi các đám cháy rừng thiêu rụi trang trại của mình, một cao bồi tên Dusty phải sống trong trại tạm cư của FEMA. Tại đây, anh tìm thấy sự gắn kết và cảm giác cộng đồng với những người cũng mất nhà cửa, trong đó có cả con gái và vợ cũ của anh.<br>&nbsp;</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1211442', 'season': None, 'voteAverage': 6.8, 'voteCount': 30}, {'id': 'tt29361963', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Trong Cái Rủi có Cái Xui', 'Untitled Home Invasion Romance', 'trong-cai-rui-co-cai-xui', '<p>Một diễn viên hết thời, nổi tiếng vì vai diễn lố bịch, tìm cách cứu vãn hôn nhân bằng một màn dàn dựng anh hùng giả. Nhưng trò lừa tình cảm nhanh chóng vượt tầm kiểm soát, đẩy anh và vợ vào tình huống một vụ án mạng thật sự.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1340076', 'season': None, 'voteAverage': 7.2, 'voteCount': 3}, {'id': 'tt33204691', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Tầm Quan', 'Search for Coffin', 'tam-quan', '<p>Năm 1939, giữa sự hỗn loạn của cuộc chiếm đóng Nhật Bản, nỗ lực cứu giúp cộng đồng đang chết đói của một người dân làng đã vô tình phát hiện ra một cổ vật huyền thoại, châm ngòi cho một chuỗi phản bội và tàn sát. Khi các thế lực cổ xưa thức tỉnh và chiến tranh cận kề, anh ta buộc phải gia nhập một đồng minh bất đắc dĩ và từ một người sống sót trở thành một kẻ nổi loạn, chiến đấu chống lại cả sự tàn bạo của con người và các thế lực siêu nhiên để bảo toàn mạng sống.</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 1, 'Full', '1', 0, false, 0, 0, '2026-02-04T20:17:30.863');
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Biệt Đội Hủy Diệt', 'The Wrecking Crew', 'biet-doi-huy-diet', '<p>Hai anh em cùng cha khác mẹ Jonny và James đoàn tụ sau cái chết bí ẩn của cha họ. Khi họ tìm kiếm sự thật, những bí mật bị chôn giấu tiết lộ một âm mưu đe dọa chia cắt gia đình họ.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1168190', 'season': None, 'voteAverage': 6.183, 'voteCount': 41}, {'id': 'tt33046197', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('13 Ngày Và Đêm', '13 Days, 13 Nights: In the Hell of Kabul', '13-ngay-va-dem', '<p>Kabul, ngày 15 tháng 8 năm 2021. Quân đội Hoa Kỳ đang chuẩn bị rút khỏi Afghanistan, trong khi Taliban đang tiến về thủ đô để giành quyền lực. Giữa cảnh hỗn loạn, Chỉ huy Mohamed Bida và đội của ông phụ trách an ninh tại Đại sứ quán Pháp, phái bộ phương Tây cuối cùng còn hoạt động. Bị mắc kẹt cùng với 500 người, bị bỏ mặc tự xoay xở, cả đội phải đến được sân bay bằng mọi giá. Một nhiệm vụ nguy hiểm không có gì đảm bảo thành công: trốn thoát khỏi địa ngục Kabul và giải cứu những người còn sót lại của nhân loại.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1254135', 'season': None, 'voteAverage': 6.647, 'voteCount': 167}, {'id': 'tt28291010', 'voteAverage': 6.7, 'voteCount': 1535}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Kẻ Có Tội', 'The Guilty', 'ke-co-toi', '<p>Một vụ bắt cóc hé lộ một vụ giết người từ cả thập kỷ trước được giấu kín trong một đoạn ghi âm cũ. Khi cuộc điều tra hé lộ những bí mật gây sốc, ba người trẻ tuổi, từng đầy triển vọng, hình thành một mối liên kết không thể phá vỡ, đối mặt với quá khứ đen tối của họ và bảo vệ lẫn nhau khỏi sự kìm kẹp của số phận.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 6', '14 Tập', 0, false, {'type': 'tv', 'id': '289723', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt34131988', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Án Phạt Dũng Giả', 'Sentenced to Be a Hero', 'an-phat-dung-gia', '<p>Ở thế giới nơi những tên tội phạm tồi tệ nhất buộc phải trở thành anh hùng và tham chiến, người đứng đầu một trại giam lập giao kèo với một nữ thần quyền năng.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '12 Tập', 0, false, {'type': 'tv', 'id': '249907', 'season': 1, 'voteAverage': 6, 'voteCount': 1}, {'id': 'tt32536168', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Người Trừ Tà', 'The Exorcist', 'nguoi-tru-ta', '<p>Khi cô bé 12 tuổi Regan có những biểu hiện kỳ quái và bạo lực không thể lý giải bằng y học, người mẹ tuyệt vọng đã tìm đến sự trợ giúp của hai linh mục Công giáo để thực hiện nghi lễ trừ tà, mở ra cuộc đối đầu khốc liệt giữa đức tin và thế lực quỷ dữ, đồng thời phơi bày nỗi sợ hãi sâu thẳm của con người trước cái ác, sự hoài nghi …</p>', 'single', 'completed', 'HD', 'Vietsub', 1973, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '9552', 'season': None, 'voteAverage': 7.7, 'voteCount': 8430}, {'id': 'tt0070047', 'voteAverage': 8.1, 'voteCount': 493216}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Vương Triều Ung Chính', 'Yongzheng Dynasty', 'vuong-trieu-ung-chinh', '<p>Phim lấy bối cảnh triều đình nhà Thanh trong giai đoạn cuối đời Khang Hy, mở đầu vương nghiệp Ung Chính. Bộ phim khai thác tính chất bi kịch của việc lập Thái tử. Để giành lấy vương quyền, các a ca, hoàng tử con vua Khang Hy đã không từ một thủ đoạn nào, bất chấp tình cha con, anh em ruột thịt , nghĩa tôi thần ... Tất cả đã tạo nên một nội bộ triều chính rối ren . ... và Tứ A Ca Dận Chân đã lập nên vương triều Ung Chính ngay trên nền chính sự như thế. Giai đoạn lịch sử nầy đã từng được một số nhà làm phim Đài Loan và Trung Quốc khai thác, tuy nhiên, nét mới trong kịch bản phim “Vương triều Ung Chính “ là ở chỗ không dàn dựng những cảnh binh đao hay dàn trải từng âm mưu đen tối mà đi sâu thể hiện tâm lý từng nhân vật, đưa ra lời giải thích hợp lý cho việc làm và cách sống của họ ...Từ đó người xem tự rút ra nhận định riêng của mình .</p>', 'series', 'completed', 'HD', 'Lồng Tiếng', 1999, 0, 'Hoàn tất (44/44)', '44 Tập', 0, false, {'type': 'tv', 'id': '80937', 'season': 1, 'voteAverage': 8.769, 'voteCount': 13}, {'id': 'tt0279520', 'voteAverage': 8.5, 'voteCount': 267}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Học Viện Thượng Lưu', 'The School', 'hoc-vien-thuong-luu', '<p>Học Viện Thượng Lưu - The School kể về cuộc chiến giữa công lý và quyền lực tại trường quốc tế ISK. Khi nam sinh nghèo Kanatee bị vu oan sau một vụ án mạng chấn động, giáo viên Key đã đứng ra bảo vệ cậu, phơi bày những góc khuất đen tối và sự thối nát đằng sau vẻ hào nhoáng của giới tinh hoa.<br>&nbsp;</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '11 Tập', 0, false, {'type': 'tv', 'id': '311142', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thanh Dao Không Muốn Làm Sát Thủ', 'How to Train Your Killer', 'thanh-dao-khong-muon-lam-sat-thu', '<p>Vào đêm tân hôn, Thái tử phi Cổ Thanh Dao bất ngờ hoán đổi linh hồn với sát thủ Thạch Nghị trong một âm mưu ám sát chồng nàng. Bị cuốn vào một trò chơi mưu mẹo và lừa dối chết người, nàng phải chiến đấu để bảo vệ thái tử đồng thời khám phá ra một âm mưu sâu rộng liên kết triều đình với thế giới võ lâm.</p>', 'series', 'completed', 'HD', 'Vietsub', 2026, 0, 'Hoàn tất (30/30)', '30 Tập', 0, false, {'type': 'tv', 'id': '311874', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thái Bình Niên', 'Swords Into Plowshares', 'thai-binh-nien', '<p>Vào thời kỳ Ngũ đại Thập quốc, trật tự chính trị sụp đổ, chiến tranh liên tục nổ ra khiến dân chúng phải sống trong lầm than. Trước tình cảnh đó, Tiền Hoằng Thục, Triệu Khuông Dận và Quách Vinh dần nhận ra rằng chỉ có thống nhất đất nước mới có thể chấm dứt được loạn lạc và tang thương. Thái Bình Niên ba theo chân ba con người mang chí lớn này trong hành trình đầy gian nan và thử thách để thực hiện khát vọng chấm dứt chiến tranh và mang lại thái bình cho dân chúng.</p>', 'series', 'ongoing', 'HD', 'Vietsub + Thuyết Minh', 2026, 0, 'Tập 15', '48 Tập', 0, false, {'type': 'tv', 'id': '279446', 'season': 1, 'voteAverage': 8, 'voteCount': 1}, {'id': 'tt32561981', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Mọi Lúc Mọi Nơi (Phần 4)', 'Whenever Possible (Season 4)', 'moi-luc-moi-noi-phan-4', '<p>Chúng tôi đang tìm người nào đó có thời gian rảnh để đi chơi cùng chúng tôi. Bất cứ khi nào có thể.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 41', '10 Tập', 0, false, {'type': 'tv', 'id': '247805', 'season': 4, 'voteAverage': 8.3, 'voteCount': 7}, {'id': 'tt34460456', 'voteAverage': 0, 'voteCount': 31}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Chuyện Lớn Nơi Thành Phố Nhỏ', 'The Dream Maker', 'chuyen-lon-noi-thanh-pho-nho', '<p>Để thúc đẩy phát triển kinh tế, huyện Bình Xuyên quyết định thành lập trấn Nguyệt Hải. Hai cán bộ trẻ có năng lực và cá tính nổi bật là Lý Thu Bình và Trịnh Đức Thành, kiên trì lý tưởng "thành phố của nhân dân do nhân dân xây dựng", đã tận dụng chính sách cải cách và Văn kiện số 1 Trung ương Đảng Cộng sản Trung Quốc để tìm ra con đường đột phá. Không sử dụng ngân sách nhà nước, họ dẫn dắt hàng chục nghìn nông dân góp vốn, liên doanh, từng bước xây dựng một đô thị hiện đại trên vùng bãi bồi hoang vu. Đây được mô tả như một kỳ tích "từ con số không", không chỉ làm thay đổi diện mạo vùng đất nghèo mà còn xoay chuyển vận mệnh của hàng trăm nghìn người nông dân Trung Quốc. Lý Thu Bình, Trịnh Đức Thành, Giải Xuân Lai, Cao Tuyết Mai cùng những người kiến tạo thành phố dám nghĩ dám làm, tiên phong đổi mới, đã viết nên một chương rực rỡ dưới ánh nắng chói chang của thập niên 1980.</p><p>&nbsp;</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 38', '40 Tập', 0, false, {'type': 'tv', 'id': '279593', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt37578672', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Bridgerton (Phần 4)', 'Bridgerton (Season 4)', 'bridgerton-phan-4', '<p>Despite his elder and younger brothers both being happily married, Benedict is loath to settle down — until he meets a captivating Lady in Silver at his mother’s masquerade ball.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '8 Tập', 0, false, {'type': 'tv', 'id': '91239', 'season': 4, 'voteAverage': 8.066, 'voteCount': 3097}, {'id': 'tt8740790', 'voteAverage': 7.4, 'voteCount': 210934}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Ngự Tứ Tiểu Ngỗ Tác (Phần 2)', 'The Imperial Coroner (Season 2)', 'ngu-tu-tieu-ngo-tac-phan-2', '<p>Aloof Prince Xiao Jinyu and imperial coroner Chu Chu navigate married life while teaming up with young investigators to solve bizarre cases and uphold peace in the Tang dynasty.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 24', '36 Tập', 0, false, {'type': 'tv', 'id': '124595', 'season': 2, 'voteAverage': 7.7, 'voteCount': 20}, {'id': 'tt14792342', 'voteAverage': 7.7, 'voteCount': 216}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Một Tình Yêu Bất Ngờ Đến', 'My Page in the 90s', 'mot-tinh-yeu-bat-ngo-den', '<p>Một bộ phim hài tình cảm nhẹ nhàng, tràn ngập tiếng cười. Khi một streamer tư vấn tình cảm của năm 2025 bị cuốn vào cuốn tiểu thuyết lãng mạn kiểu cũ, cô đã chạm trán anh sếp tổng ngang ngược năm 1999, trông tưởng vô hại mà rất xảo quyệt. Màn đối đầu cuối cùng giữa lối mòn và gậy ông đập lưng ông của cả hai chính thức mở ra, ai sẽ là người giành phần thắng sau cùng? Để trở về thế giới hiện thực quen thuộc, streamer tư vấn tình cảm Lâm Hoan Nhi bắt đầu tung ra hàng loạt chiêu thức chinh phục sếp tổng ngang ngược Cao Hải Minh. Thế nhưng, thông minh quá hóa phản tác dụng. Khi đã dốc hết sức vượt ải và buộc phải rời khỏi thế giới trong sách, cô mới nhận ra mình đã lún sâu từ lâu, chẳng nỡ rời đi. Từ "muốn đi mà vẫn phải ở lại" đến "muốn ở lại nhưng vẫn phải đi", ở đoạn kết của câu chuyện, liệu những người yêu nhau có thể nên duyên trọn vẹn?</p><p>&nbsp;</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 16', '24 Tập', 0, false, {'type': 'tv', 'id': '280916', 'season': 1, 'voteAverage': 10, 'voteCount': 1}, {'id': 'tt35238161', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Sắc Đêm Ngập Tràn', 'The Glamorous Night', 'sac-dem-ngap-tran', '<p>Dưới vỏ bọc của một bữa tiệc thịnh soạn đã khiến sóng ngầm giấu kín bấy lâu nay trỗi dậy, đánh thức tất cả những kẻ đang giả vờ ngủ say, đồng thời kích hoạt mối nguy sinh tồn lan rộng khắp các cấp bậc tại tập đoàn rượu GST. Khi mọi thứ đều là vấn đề sống còn, mỗi bước đi đều đòi hỏi sự cẩn trọng tột độ. Bảy nhân vật chính bị cuốn sâu vào vòng xoáy ấy, mỗi người đóng một vai trò khác nhau, cùng nhau phác họa nên sự phức tạp của lòng người và sự tàn khốc của thực tại. Tất cả cùng hướng đến một chủ đề chung: Làm thế nào để có thể sống lạc quan giữa những tháng ngày đầy rẫy bất an và lo sợ!</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 5', '24 Tập', 0, false, {'type': 'tv', 'id': '259554', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt30829335', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Những Ngày Vàng Son', 'Our Golden Days', 'nhung-ngay-vang-son', '<p>Ai cũng có những ngày tháng huy hoàng của riêng mình. Dù là hiện tại, quá khứ hay tương lai.'' Một bộ phim tâm lý gia đình gây tiếng vang qua nhiều thế hệ về những ngày tháng huy hoàng, mỗi ngày đều mang một ý nghĩa riêng.</p>', 'series', 'completed', 'HD', 'Vietsub', 2025, 0, 'Hoàn tất (50/50)', '50 Tập', 0, false, {'type': 'tv', 'id': '287010', 'season': 1, 'voteAverage': 10, 'voteCount': 2}, {'id': 'tt37876545', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Cơn Say Mùa Xuân', 'Spring Fever', 'con-say-mua-xuan', '<p>Câu chuyện kể về Yun Bom, người sau khi trải qua những biến động tình cảm ở Seoul, chuyển đến thị trấn nhỏ Sinsu để bắt đầu cuộc sống mới với tư cách là một giáo viên trao đổi. Ban đầu, cô tỏ ra xa cách và lạnh lùng với mọi người, nhưng dần dần mở lòng sau khi gặp Seon Jae Gyu. Seon Jae Gyu là một nhân vật quan trọng, thường xuyên gây náo loạn trong làng bằng những trò quậy phá của mình. Anh cũng là Giám đốc điều hành của JK Power Energy và là chú của Seon Han Gyeol, một học sinh trường Trung học Sinsu. Mặc dù vóc dáng to lớn và vẻ ngoài thô ráp, thoạt nhìn giống như một gã giang hồ đường phố, Jae Gyu lại là người đầy quyến rũ bất ngờ, lòng tận tụy không lay chuyển và sự quan tâm sâu sắc đến người khác.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 8', '12 Tập', 0, false, {'type': 'tv', 'id': '280948', 'season': 1, 'voteAverage': 8.5, 'voteCount': 2}, {'id': 'tt39137681', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thư Gửi Tuổi Trẻ Của Tôi', 'A Letter to My Youth', 'thu-gui-tuoi-tre-cua-toi', '<p>Một thiếu niên nổi loạn và một người quản lý trầm lặng tạo nên sợi dây gắn kết lạ thường tại mái ấm nọ khi cả hai thỏa hiệp với quá khứ đau thương.</p>', 'single', 'completed', 'HD', 'Vietsub', 2026, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1602705', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Xà Thần Lấy Vợ', 'The Long Snake Takes a Wife', 'xa-than-lay-vo', '<p>Mẹ của Bạch Trung Thiên năm xưa gặp nạn một cách ly kỳ. Dân làng đều đồn đoán, nói bà đã bị Trường Tiên bắt đi. Nhiều năm sau, Bạch Trung Thiên một lần nữa quay trở lại trấn Bạch Vân. Những truyền thuyết quái dị như Trường Tiên cưới vợ, cắt giấy gọi hồn, gánh hát ma, hay chiếc ô giấy đỏ đã phủ lên trấn Bạch Vân một tấm màn huyền bí. Có dân làng trong lúc đi đốn củi lại tình cờ nhìn thấy Trường Tiên rước dâu. Bạch Trung Thiên quyết tâm lần theo manh mối, phơi bày sự thật ra ánh sáng.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 19', '22 Tập', 0, false, {'type': 'tv', 'id': '290448', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Góc Tối', 'The Unseen', 'goc-toi', '<p>Nhằm truy tìm sự thật đằng sau vụ “tự sát” của chị gái, blogger Thẩm Mạn bị cuốn vào một vụ án vô cùng ly kỳ: trưởng khoa sản phụ khoa Ái Hạ bị cắt bỏ tử cung, đồng thời cô bị đưa vào diện tình nghi hàng đầu. Nữ cảnh sát Khương Lê ra tay giúp cô minh oan. Một tấm bưu thiếp kết nối hai vụ án với nhau đã buộc hai người vốn ở thế đối lập phải bắt tay hợp tác. Thế nhưng, vụ án mạng thứ hai lại tiếp tục xảy ra, màn sương bí ẩn lại ngày càng dày đặc…</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 6', '24 Tập', 0, false, {'type': 'tv', 'id': '290983', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Cận Tử', 'Near Death', 'can-tu', '<p>Sau khi suýt tự kết liễu đời mình, Julia đối mặt với những dày vò siêu nhiên khi các linh hồn bị tra tấn bám lấy cơ thể cô và nguyên nhân có thể gắn liền với quá khứ của cô.</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1566038', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Con Ngoan', 'A Good Child', 'con-ngoan', '<p>Trở về chăm sóc người mẹ xa cách đang mắc chứng mất trí, một drag queen tài năng đóng giả làm cô con gái thất lạc từ lâu của bà, với hi vọng hàn gắn lại mối quan hệ giữa họ.</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1287782', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt38637298', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Trò Chơi Hẹn Hò', 'Dating Game', 'tro-choi-hen-ho', '<p>Một lập trình viên game nhút nhát hết lòng với "bạn gái" avatar, vào làm việc tại công ty tạo ra cô ấy, rồi bất ngờ rung động trước một người ngoài đời thực, khiến mọi thứ đảo lộn.</p>', 'series', 'completed', 'HD', 'Vietsub', 2025, 0, 'Hoàn tất (12/12)', '12 Tập', 0, false, {'type': 'tv', 'id': '283717', 'season': 1, 'voteAverage': 5.5, 'voteCount': 2}, {'id': 'tt37369080', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đứa Con Của Thần Tượng (Phần 3)', '【OSHI NO KO】Season 3', 'dua-con-cua-than-tuong-phan-3', '<p>"Trong giới thần tượng, nói dối chính là vũ khí." Goro, người làm bác sĩ sản phụ khoa ở một thành phố nhỏ, hàng ngày sống một cuộc sống không liên quan gì đến ngành giải trí. Mặt khác, thần tượng Hoshino Ai mà anh "ủng hộ" bắt đầu thăng hạng trong danh sách các ngôi sao. Hai người đã có cuộc gặp gỡ tồi tệ nhất, và bánh răng của số phận bắt đầu quay từ đó</p>', 'series', 'ongoing', 'FHD', 'Vietsub', 2026, 0, 'Tập 3', '13', 0, false, {'type': 'tv', 'id': '203737', 'season': 3, 'voteAverage': 8.344, 'voteCount': 288}, {'id': 'tt21030032', 'voteAverage': 8.2, 'voteCount': 13583}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Sụp đổ (Phần 2)', 'Fallout (Season 2)', 'sup-do-phan-2', '<p>Picking up in the aftermath of Season One''s epic finale, follow along as Lucy and The Ghoul journey through the wasteland of the Mojave to the post-apocalyptic city of New Vegas.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 7', '8 Tập', 0, false, {'type': 'tv', 'id': '106379', 'season': 2, 'voteAverage': 8.2, 'voteCount': 2198}, {'id': 'tt12637874', 'voteAverage': 8.3, 'voteCount': 342558}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Nhờ Kim Đan, Tôi Gánh Cả Tông Môn', 'The sect of pros and their beginner senior', 'nho-kim-dan-toi-ganh-ca-tong-mon', '<p>Đại sư huynh Trần Trường Sinh kẻ bị xem là “vô dụng” nhất toàn giới tu luyện hao tốn trăm năm trời cuối cùng cũng kết thành Kim Đan. Anh quyết tâm sử dụng tu vi “mạnh mẽ” của mình để bảo vệ các sư muội, sư đệ “tài năng bình thường nhưng vận số cực kỳ tốt.” trong môn phái. Điều anh không hề hay biết là: từ tông chủ cho đến đệ tử tạp dịch của Thanh Vân Đạo Tông, tất cả đều là các thần thánh và bậc đại nhân đã phi thăng nhưng vẫn ở lại thế gian vì anh. Mục tiêu duy nhất của họ trong kiếp này là bảo vệ người có ký ức và sức mạnh đều bị phong ấn: vị Đạo Tổ khai thiên lập địa Trần Trường Sinh.</p>', 'hoathinh', 'completed', 'FHD', 'Vietsub', 2026, 0, 'Hoàn tất (80/80)', '80', 0, false, {'type': 'tv', 'id': '', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Nguyên Tội (Phần 2)', 'Original Sin (Season 2)', 'nguyen-toi-phan-2', '<p>Chuyên gia pháp y Đới Vũ và thám tử Trịnh Minh bị cuốn vào một loạt vụ án mạng kinh hoàng có liên quan đến một vụ bắt cóc chưa được giải quyết từ nhiều năm trước. Khi những bí mật bị chôn vùi dần lộ diện và các manh mối bắt đầu kết nối lại với nhau, họ phải chạy đua với thời gian để phơi bày sự thật và đưa kẻ thủ ác thực sự ra trước ánh sáng công lý.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 16', '24 Tập', 0, false, {'type': 'tv', 'id': '262531', 'season': 2, 'voteAverage': 8, 'voteCount': 1}, {'id': 'tt33507627', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Liệu Pháp Sự Thật (Phần 3)', 'Shrinking (Season 3)', 'lieu-phap-su-that-phan-3', '<p>Jimmy and his rag-tag crew pick up the pieces of last season, forcing them to reckon with grief, second chances, and the messy road toward healing. With old clients still reeling and a few new faces entering the fold</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 1', '11 Tập', 0, true, {'type': 'tv', 'id': '136311', 'season': 3, 'voteAverage': 7.792, 'voteCount': 517}, {'id': 'tt15677150', 'voteAverage': 8.1, 'voteCount': 105904}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Nữ Thần Bàng Thượng Nhãn', 'The Inner Eye', 'nu-than-bang-thuong-nhan', '<p>Nữ luật sư bất bại Tang Yingying đối đầu trực diện với cấp trên nghiêm khắc Kang Jun khi xử lý hàng loạt vụ án thực tế, phơi bày mâu thuẫn giữa tình cảm con người và nguyên tắc pháp luật trong xã hội Trung Quốc hiện đại. Khi cuộc cạnh tranh nghề nghiệp của họ diễn ra, cả hai buộc phải đối mặt với những lựa chọn liên quan đến tình yêu, gia đình và tham vọng—dẫn họ đến sự trưởng thành cá nhân và hiểu biết sâu sắc hơn về công lý.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 12', '30 Tập', 0, true, {'type': 'tv', 'id': '283950', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Nửa Tỉnh Nửa Mê', 'Half Awake', 'nua-tinh-nua-me', '<p>Ông trùm thương mại Cố Dịch Tiêu nổi tiếng lạnh lùng tàn nhẫn, chỉ riêng cô thư ký Diệp Tinh Vãn là điểm yếu chí mạng của anh. Vì một hiểu lầm từ 15 năm trước, anh đã giăng bẫy để khống chế và dày vò cô. Nhưng cô gái Diệp Tinh Vãn với vẻ ngoài tưởng chừng yếu mềm ấy đã không còn cam chịu. Cô tương kế tựu kế, lấy chính bản thân làm mồi nhử, cuốn Cố Dịch Tiêu vào một mối tình đầy đau đớn khi mà yêu và hận cứ thế đan xen. Đến cuối cùng, cô cũng chấp nhận sự sám hối của Cố Dịch Tiêu và dấy lên cho anh tia hy vọng được cứu rỗi mong manh. Thế nhưng, liệu trái tim cô có thể thật sự được bình yên và hạnh phúc hay không? Đó là câu hỏi vẫn còn đang bỏ ngỏ.</p><p>&nbsp;</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 22', '24 Tập', 0, false, {'type': 'tv', 'id': '294615', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thảm Họa Thiên Thạch 2: Di Tản', 'Greenland 2: Migration', 'tham-hoa-thien-thach-2-di-tan', '<p>Sau ngày tận thế, gia đình Garrity rời boong-ke an toàn ở Greenland, mạo hiểm tất cả để bước vào một hành trình đầy hiểm nguy, băng qua vùng đất hoang tàn của châu Âu nhằm tìm kiếm một mái nhà mới.<br>&nbsp;</p>', 'single', 'completed', 'HD', 'Vietsub', 2026, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '840464', 'season': None, 'voteAverage': 6.514, 'voteCount': 109}, {'id': 'tt14850054', 'voteAverage': 5.8, 'voteCount': 3032}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Võ Toái Tinh Hà', 'Shattering the Galaxy | Martial Conqueror of the Cosmos', 'vo-toai-tinh-ha', '<p>Võ Toái Tinh Hà là hành trình rèn luyện và chiến đấu đầy gian khổ và cũng không kém phần lý thú của một thanh niên có tên Giang Hàn. Chẳng hiểu vì lý do khó hiểu nào đó mà Giang Hàn lại phải sống cô độc nơi núi rừng hoang vu u ám, một tia nhất niệm trong lòng cậu là luôn mong muốn tìm lại cha mẹ của mình, được sống trong sự ấm áp của mái ấm gia đình, vậy nên cậu quyết tâm sẽ rèn luyện bản thân, bước ra thế giới đầy chông gai kia để có thể hy vọng tìm được cha mẹ. Điều may mắn xảy đến khi Thiên Thú Đỉnh mà mẹ cậu truyền lại từ khi cậu con rất nhỏ thì nay đã được giải phóng, nó biến Giang Hàn thành một con người hoàn toàn khác, có những khả năng chiến đấu phi phàm, cũng có thể coi là bất khả chiến bại.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 51', '100 Tập', 0, false, {'type': 'tv', 'id': '298196', 'season': 1, 'voteAverage': 7, 'voteCount': 1}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thế Giới Hoàn Mỹ', 'Perfect World', 'the-gioi-hoan-my', '<p>Thới Giới Hoàn Mỹ là phim hoạt hình kể về quá trình trưởng thành của một đứa trẻ trời sinh Chí Tôn cốt (đứa bé này tương lai có thể sánh vai cùng hung Thái cổ được trời ưu ái), có thể chinh chiến với Chân Hống, Kim Sí Đại Bàng có huyết mạnh tinh thuần đến hoàn mỹ, Nguyên thủy bảo thuật của nó sẽ danh chấn thiên hạ, được ghi khắc vào lịch sử của dân tộc.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub + Thuyết Minh', 2021, 621, 'Tập 252', '255', 0, false, {'type': 'tv', 'id': '124003', 'season': 1, 'voteAverage': 8.45, 'voteCount': 20}, {'id': 'tt14986786', 'voteAverage': 8.3, 'voteCount': 749}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Song Sinh Võ Hồn', 'The Rise of Twin Souls', 'song-sinh-vo-hon', '<p>Từng được coi là một truyền nhân của một gia thế lẫy lừng ở Đại Lâm quận, anh chàng Lâm Phàm thậm chí còn được coi là một thiếu niên thiên tài với những thiên phú thiên bẩm, nhưng biến cố đã bắt đầu xảy đến với Lâm Phàm khi mà vị hôn thê đầu ấp tay gối của anh đã không chút thương tiếc nào mà lấy đi hết sạch võ hồn của anh. Không còn võ hồn nữa, Lâm Phàm bị coi như một tên phế vật. Nhưng số phận của anh chưa thảm họa đến mức như vậy, một loại đại ma bí ẩn từ lâu ký sinh trên người đã giúp anh không chỉ thức tỉnh lại võ hồn đã mất, mà còn mang đến cho anh thêm một loại võ hồn mới nữa, để từ đó biến Lâm Phàm từ một anh hùng hạng xoàng trở thành một con người hoàn toàn mới, bước ra thiên hạ với chiến công hiển hách.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 59', 'Đang cập nhật', 0, false, {'type': 'tv', 'id': '290681', 'season': 1, 'voteAverage': 7, 'voteCount': 1}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Ba Đường Luân Hồi', 'Secrets of the Rivers', 'ba-duong-luan-hoi-2025', '<p>Ba con sông Hoàng Hà, Trường Giang và Lan Thương có cùng chung một nguồn. Nhà họ Đinh, nhà họ Khương và nhà họ Dịch, ba gia tộc Thủy Quỷ sinh sống dọc theo những con sông ấy. Họ được trời phú cho khả năng tự do di chuyển dưới nước, lại tinh thông phong thuỷ, long mạch và thuật tìm báu vật. Dịch Táp là Thủy Quỷ cuối cùng của nhà họ Dịch, hiện đang quản lý “ngân hàng dưới nước” trên dòng sông Lan Thương. Trong một lần mở “Kim Thang”, kho báu dưới nước, cô bất ngờ cứu được Tông Hàng. Để phơi bày chân tướng vụ án năm xưa và bảo toàn mạng sống, Dịch Táp đã huấn luyện Tông Hàng trở thành một Thủy Quỷ thực thụ. Hai người họ cùng Thủy Quỷ Đinh Ngọc Điệp của nhà họ Đinh đã xông pha xuống dòng nước sâu để tiến vào "Tổ Nguyên Kim Thang", kho báu của tổ tiên.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 14', '18', 0, false, {'type': 'tv', 'id': '297999', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Kiếm Lai (Phần 2)', 'Sword of Coming (Season 2)', 'kiem-lai-phan-2', '<p>Thế giới rộng lớn không thiếu cái lạ. Trần Bình An ta chỉ với một kiếm, có thể dời núi, lấp biển, hàng yêu, trấn ma, phong thần, chém sông, phá thành, mở trời mở đất.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 8', '26 Tập', 0, false, {'type': 'tv', 'id': '259537', 'season': 2, 'voteAverage': 9.2, 'voteCount': 16}, {'id': 'tt33132245', 'voteAverage': 7.8, 'voteCount': 149}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đại Đường Thừa Phong Lục', 'Wind Driver in Tang Dynasty', 'dai-duong-thua-phong-luc', '<p>Một biến cố lớn xảy ra khi sư phụ Mục Thiên Hậu, bậc Thánh Thủ lừng danh giang hồ, bất ngờ bị kẻ gian hãm hại. Từ đó, giang hồ dậy sóng, mở ra hành trình đầy bi hài của hai huynh đệ vừa mới kết giao: Tổ Bi Thu và Trịnh Đông Đình. Đông Đình quyết định cùng sư đệ truy tìm tung tích người vợ mất tích và manh mối kẻ đã ra tay sát hại sư phụ. Nhưng trên đường đi, họ lại bị vu oan là hung thủ trong một vụ thảm sát, trở thành mục tiêu truy đuổi của nhiều môn phái. Càng tìm cách minh oan, mọi hiểu lầm càng chồng chất. Cuối cùng, nhờ thần kiếm Mãn Thiên Tinh, cả hai đánh bại được Cung Thiên Ảnh - kẻ chủ mưu đứng sau tất cả. Minh oan cho bản thân, họ tiếp tục dấn thân vào con đường trả thù, hướng về Côn Luân tìm Đốc Hồng Hoa.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 21', '26 Tập', 0, false, {'type': 'tv', 'id': '280952', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Kiếm Cơm Bằng Trò Chơi Sinh Tử', 'SHIBOYUGI: Playing Death Games to Put Food on the Table', 'kiem-com-bang-tro-choi-sinh-tu', '<p>Yuki kiếm sống bằng các trò chơi tử thần. Nhưng khi tỉnh dậy trong dinh thự cùng năm cô gái khác, liệu cô có sống sót trong mê cung chết người mới với vô số phòng khóa kín và bẫy?</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '11 Tập', 0, false, {'type': 'tv', 'id': '263330', 'season': 1, 'voteAverage': 1, 'voteCount': 1}, {'id': 'tt33309549', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Mặt Khuất Của Tamon-kun', 'Tamon''s B-Side', 'mat-khuat-cua-tamon-kun', '<p>Utage Kinoshita is a high school girl who works part-time as a housekeeper. She has devoted her life to her favorite idol, Tamon Fukuhara, from the group F/ACE. Then one day, Utage ends up being assigned to Tamon’s house! There she discovers that off-stage, he is nothing like his wild idol persona. A gloomy, introverted boy with no self-confidence, Utage still finds herself falling for him anyway.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 5', '12 Tập', 0, false, {'type': 'tv', 'id': '276393', 'season': 1, 'voteAverage': 0, 'voteCount': 1}, {'id': 'tt37532722', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Beast Games (Phần 2)', 'Beast Games (Season 2)', 'beast-games-phan-2', '<p>After a record-shattering first season, Beast Games is back! With a life-changing $5,000,000 prize on the line, MrBeast brings together 100 of the strongest and 100 of the smartest players on the planet. Will it be superhuman strength or super genius that takes home the grand prize? Each game will test the limits of human strength, intelligence, and strategy. What WOULDN''T you do for $5,000,000?</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 6', '10 Tập', 0, false, {'type': 'tv', 'id': '249522', 'season': 2, 'voteAverage': 7.4, 'voteCount': 173}, {'id': 'tt31812476', 'voteAverage': 5.8, 'voteCount': 16369}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Khử Tà Diệt Ma', 'My Date with a Vampire', 'khu-ta-diet-ma', '<p>Khử Tà Diệt Ma mở đầu bằng câu chuyện tình yêu định mệnh giữa nhân loại và cương thi, đan xen với những cuộc chiến giữa thiện – ác, người – ma trong thế giới huyền ảo.<br>Nhân vật chính Mã Tiểu Linh (Dương Tư Kỳ) là người thừa kế của dòng tộc diệt ma trứ danh, có nhiệm vụ trấn áp cương thi và tà linh. Trong một lần hành động, cô tình cờ gặp Cửu Ca (Trịnh Y Kiện) – một cương thi mang linh hồn con người, không sát hại ai và luôn đấu tranh để giữ lại phần nhân tính trong mình. Giữa hai người dần nảy sinh tình cảm, nhưng tình yêu ấy lại bị ngăn cấm bởi ranh giới sinh – tử và định mệnh nghiệt ngã.<br>Bộ phim kết hợp xuất sắc yếu tố võ thuật, kinh dị, tâm linh và lãng mạn, tạo nên một vũ trụ cương thi độc đáo của ATV, đồng thời gửi gắm thông điệp nhân văn: “Dù là người hay ma, chỉ cần có trái tim biết yêu thương, vẫn xứng đáng được sống như một con người.”</p>', 'series', 'ongoing', 'HD', 'Lồng Tiếng', 1998, 0, 'Tâp 0', '35 Tập', 0, false, {'type': 'tv', 'id': '19389', 'season': 1, 'voteAverage': 8.6, 'voteCount': 7}, {'id': 'tt0874636', 'voteAverage': 7.9, 'voteCount': 112}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Hoang Đảo 3 Người', 'Three', 'hoang-dao-3-nguoi', '<p>After a yachting accident, a millionaire and his wife are shipwrecked on a desert island along with their former deckhand, Manuel.</p>', 'single', 'ongoing', 'HD', 'Vietsub', 2005, 0, 'Tâp 0', '1', 0, false, {'type': 'movie', 'id': '9753', 'season': None, 'voteAverage': 5.554, 'voteCount': 277}, {'id': 'tt0377309', 'voteAverage': 4.9, 'voteCount': 10882}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Công Tố Viên Phi Thường', 'The Unusual Prosecutor', 'cong-to-vien-phi-thuong', '<p>Bộ phim kể về hành trình của một công tố viên có tư duy và phương pháp phá án khác thường tại Hồng Kông, anh cùng các cộng sự trong ngành tư pháp phải đối mặt với những vụ án pháp lý phức tạp, xung đột quyền lực và áp lực chính trị, qua đó dần lật mở mặt tối của hệ thống luật pháp, những bí mật bị che giấu và các lựa chọn đạo đức đầy giằng xé giữa công lý, lương tâm và lợi ích cá nhân.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tâp 0', '25 Tập', 0, false, {'type': 'tv', 'id': '275631', 'season': 1, 'voteAverage': 7, 'voteCount': 1}, {'id': 'tt33303703', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Người Đàn Ông Đầu Tiên', 'First Man', 'nguoi-dan-ong-dau-tien', '<p>Bộ phim khắc họa cuộc đối đầu sinh tử giữa một người phụ nữ giết người để trả thù và một người phụ nữ khác giết người vì dục vọng của chính mình.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 25', '120 Tập', 0, false, {'type': 'tv', 'id': '303076', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Gia Đình Ngụy Trang', 'Disguised Family', 'gia-dinh-nguy-trang', '<p>Điệp viên hàng đầu <strong>Nam Thái Vân</strong> cùng chàng điệp viên tự luyến <strong>Nghiêm Ứng Tuấn</strong> buộc phải đóng giả vợ chồng, thậm chí nhận nuôi một cô con gái “giả”, để thâm nhập vào giới thượng lưu đầy bí mật.</p><p>Giữa những nhiệm vụ nguy hiểm, âm mưu và dối trá chồng chất, cả ba phải diễn tròn vai một gia đình hoàn hảo. Thế nhưng, trong quá trình kề vai sát cánh vượt qua sinh tử, những cảm xúc vốn chỉ là giả dần trở nên chân thật.</p><p>Từ một “vỏ bọc nhiệm vụ”, họ bất ngờ tìm thấy thứ mà mình chưa từng có — một mái ấm thực sự.</p>', 'series', 'completed', 'HD', 'Vietsub', 2026, 0, 'Hoàn tất (26/26)', '26 Tập', 0, false, {'type': 'tv', 'id': '279873', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Trí Tuệ Tiềm Năng (Phần 2)', 'High Potential', 'tri-tue-tiem-nang-phan-2', '<p>Sau thành công của mùa đầu tiên, Morgan Gillory (Kaitlin Olson) - bà mẹ đơn thân thông minh xuất chúng với chỉ số IQ 160 – tiếp tục trở lại trong mùa 2 của High Potential.&nbsp;</p><p>Ở mùa 1, Morgan từ một nhân viên dọn dẹp bình thường đã khiến Sở cảnh sát Los Angeles phải kinh ngạc bởi khả năng quan sát và suy luận thiên tài. Nhưng bên cạnh những vụ án hóc búa, cô cũng phải đối diện với những rắc rối riêng tư: nuôi dạy ba đứa con nhỏ và mối quan hệ phức tạp giữa mình và Karadec bước sang một giai đoạn mới, khi cả hai vừa phải hợp tác phá án, vừa phải giải quyết cảm xúc cá nhân. Mùa 2 mở ra nhiều thử thách mới. Một kẻ thù nguy hiểm, "Game Maker", tiếp tục thách thức trí tuệ của Morgan với những trò chơi chết chóc, đặt gia đình cô vào vòng nguy hiểm.&nbsp;</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 11', '13 Tập', 0, false, {'type': 'tv', 'id': '226637', 'season': 2, 'voteAverage': 8.044, 'voteCount': 354}, {'id': 'tt22091076', 'voteAverage': 7.6, 'voteCount': 37391}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Ranh Giới Định Mệnh', 'Bound by Fate', 'ranh-gioi-dinh-menh', '<p>Ateş, một người đàn ông bị ám ảnh bởi những vết sẹo tuổi thơ và bị nhấn chìm trong cơn thịnh nộ, trở về để hủy diệt gia đình đã tàn phá cuộc đời anh nhiều năm trước. Vũ khí của anh không phải là thanh kiếm, mà là một cuộc hôn nhân: 187 ngày với Mercan, con gái của kẻ thù anh. Mercan, người đã hứa hôn với Nezir, bị cuốn vào một cuộc chiến mà cô không hề lựa chọn, trong khi Ateş ràng buộc cô với mình vì tin rằng cô là chìa khóa cho sự trả thù của anh. Tuy nhiên, người phụ nữ mà anh định hủy diệt lại trở thành người đe dọa đến sự nghiệp của anh. Và trong bóng tối, Aslı – bị thúc đẩy bởi lòng ghen tuông, nắm bắt mọi cơ hội để chia rẽ họ.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 10', '10 Tập', 0, false, {'type': 'tv', 'id': '306118', 'season': 1, 'voteAverage': 9.667, 'voteCount': 3}, {'id': 'tt39013436', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Burnout Syndrome: Hội Chứng Kiệt Sức', 'Burnout Syndrome', 'burnout-syndrome-hoi-chung-kiet-suc', '<p>Sau khi mất đi công việc mơ ước, một nghệ sĩ kiệt sức rơi vào tình thế khó xử giữa hai người đàn ông - một anh chàng IT quyến rũ và một ông trùm ẩn dật thuê anh làm gương mặt đại diện cho mình.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 9', '10 Tập', 0, false, {'type': 'tv', 'id': '278142', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt34919837', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Vòng Xoáy Giả Tạo', 'A Graceful Liar', 'vong-xoay-gia-tao', '<p>Miêu tả câu chuyện về hai người phụ nữ dâm đãng, một người mẹ và một người con gái có quan hệ huyết thống và giờ đây gặp nhau với tư cách là mẹ chồng và cùng nhau chiến đấu bằng lời nói dối để chiếm lấy cung điện vàng.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 82', '? Tập', 0, false, {'type': 'tv', 'id': '297659', 'season': 1, 'voteAverage': 7.5, 'voteCount': 2}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Hoàng Hậu Giá Lâm', '皇后驾到', 'hoang-hau-gia-lam', '<p>Nữ diễn viên hàng đầu tái sinh thành con gái của một vị tướng, liên minh với một hoàng tử để đánh bại kẻ thù và vạch trần một âm mưu đẫm máu.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 12', '24 Tập', 0, false, {'type': 'tv', 'id': '295890', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Nhật Ký Khủng Long (Phần 8)', 'Gg Bond (Season 8)', '猪猪侠之恐龙日记-phan-8', 'Nhật Ký Khủng Long (Phần 8)-Gg Bond (Season 8) (2024) [HD-Thuyết Minh]', 'hoathinh', 'completed', 'HD', 'Thuyết Minh', 2024, 0, 'Hoàn Tất (26/26)', '26 Tập', 0, false, {'type': 'tv', 'id': '120738', 'season': 8, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Lãnh chúa vô tư vui thú bảo vệ lãnh địa ~ Biến ngôi làng vô danh thành pháo đài mạnh nhất bằng ma pháp hệ sản xuất ~', 'Easygoing Territory Defense by the Optimistic Lord', 'lanh-chua-vo-tu-vui-thu-bao-ve-lanh-dia-bien-ngoi-lang-vo-danh-thanh-phao-dai-manh-nhat-bang-ma-phap-he-san-xuat', '<p>Tái sinh thành con trai thứ tư của một hầu tước, Van từng được ca ngợi là thần đồng thiên tài—cho đến khi cậu bị đày đến một ngôi làng biên giới vô danh vì sở hữu Ma thuật Sản xuất, một loại ma thuật vô dụng trong thế giới này. Nhưng khi cậu sử dụng sức mạnh “vô dụng” của mình để chế tạo vũ khí, công cụ và những kỳ quan vượt ngoài sức tưởng tượng, ngôi làng bắt đầu phát triển thịnh vượng! Điều bắt đầu như một cuộc sống lưu đày giờ đây là khởi đầu của một cuộc sống mới—và một cuộc phiêu lưu thay đổi thế giới!</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '12 Tập', 0, false, {'type': 'tv', 'id': '288589', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt38977386', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Tâm Trí Rực Rỡ (Phần 2)', 'Brilliant Minds (Season 2)', 'tam-tri-ruc-ro-phan-2', '<p>Bộ phim đưa khán giả vào một thế giới đầy mê hoặc của khoa học thần kinh, nơi những khám phá mới về bộ não liên tục được hé lộ. Qua đó, khán giả sẽ cùng các nhân vật trải nghiệm những cảm xúc thăng trầm, những mối quan hệ phức tạp và những câu hỏi về bản chất con người.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 13', '22 Tập', 0, false, {'type': 'tv', 'id': '237748', 'season': 2, 'voteAverage': 7.4, 'voteCount': 41}, {'id': 'tt26448526', 'voteAverage': 7.1, 'voteCount': 4565}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Citadel: Honey & Bunny', 'Citadel Honey Bunny', 'citadel-honey-and-bunny', '<p>Citadel: Honey Bunny là phần phim truyền hình hành động gián điệp Ấn Độ nói tiếng Anh, thuộc vũ trụ “Citadel”. Đây là phần tiền truyện về cha mẹ của Nadia Sinh - nhân vật chính trong Citadel mùa 1 bản Mỹ (Citadel 2023).<br>Citadel: Honey Bunny xoay quanh mối quan hệ giữa Bunny, một diễn viên đóng thế kiêm điệp viên ngầm, và Honey, một nữ diễn viên đang chật vật tìm chỗ đứng trong sự nghiệp. Một ngày nọ, Bunny chiêu mộ Honey tham gia vào một "công việc phụ" nhưng thực chất là một nhiệm vụ gián điệp nguy hiểm cho một tổ chức bí mật do Baba (Kay Kay Menon) điều hành. Từ những người xa lạ, họ cùng nhau trải qua những phi vụ nghẹt thở, nảy sinh tình cảm và bị cuốn sâu vào thế giới của sự phản bội và âm mưu chính trị.<br>Phim được khen ngợi nhờ các pha hành động thực tế, thô bạo, và đầy kịch tính mang phong cách “John Wick phiên bản Ấn Độ” kết hợp với kỹ thuật quay phim hiện đại. Sự kết hợp giữa Varun Dhawan (Bunny) và Samantha Ruth Prabhu (Honey) được đánh giá cao về mặt cảm xúc. Đặc biệt, Samantha có màn lột xác ấn tượng từ một cô gái yếu đuối thành một đả nữ thực thụ. Đây là bộ phim không thể bỏ qua dành cho các tín đồ thể loại hành động-gián điệp có nhịp nhanh và nhiều pha hành động mãn nhãn.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2024, 0, 'Tập 3', '6 Tập', 0, false, {'type': 'tv', 'id': '154084', 'season': 1, 'voteAverage': 6.792, 'voteCount': 72}, {'id': 'tt27111295', 'voteAverage': 6.2, 'voteCount': 8894}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Nhà Ga Nuốt Chửng', 'Kisaragi Station Re:', 'nha-ga-nuot-chung', '<p>Haruna Tsunematsu (Yuri Tsunematsu) đang học nghiên cứu về chuyên ngành văn hoá dân gian tại trường đại học. Cô quyết định lựa chọn truyền thuyết đô thị nổi tiếng là “Nhà ga Kisagari” để làm luận văn tốt nghiệp. Đây là câu chuyện rùng rợn từng được lưu truyền và khuấy đảo cộng động mạng vào năm 2004. Trong suốt quá trình thu thập tài liệu, Haruma gặp một người phụ nữ có tên là Junko Hayama (Eriko Sato). Nhiều lời đồn cho rằng, Junko chính là người đã đăng câu chuyện trên lên mạng với tên gọi “Hasumi”. Junko kể cho Haruna rằng cô đã lưu lạc tới một thế giới khác, và điều đó đã dẫn Haruna tới ga tàu Kisaragi - khởi nguồn của truyền thuyết đô thị rùng rợn năm xưa…</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1414305', 'season': None, 'voteAverage': 5.7, 'voteCount': 3}, {'id': 'tt35316972', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Mặt Trời Chiếu Rọi Thanh Xuân', 'The Way Out', 'mat-troi-chieu-roi-thanh-xuan', '<p>Hà Lập Vy, một lập trình viên trẻ tài năng, làm việc cho Công ty phần mềm Homeland và tự mình phát triển một trò chơi. Chứng hoang tưởng và hành động của anh đã phá vỡ kế hoạch tài chính của công ty và sau đó đã bị đưa đến bệnh viện phục hồi chức năng tâm thần "Thanh Xuân Lý". Tại trung tâm phục hồi chức năng, Hà Lập Vy đã gặp nhiều bệnh nhân và trải qua nhiều câu chuyện buồn cười. Trong số đó, bệnh nhân nữ Lâm Xuân Xuân.<br>&nbsp;</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1445905', 'season': None, 'voteAverage': 6.8, 'voteCount': 4}, {'id': 'tt36118986', 'voteAverage': 0, 'voteCount': 59}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Kinh Doanh Tình Yêu', 'Liar, Liar, Love is on Fire', 'kinh-doanh-tinh-yeu', '<p>Cặp đôi mạng xã hội Từ Hiểu Lệ và “bạn trai giả” Hạo Trác rơi vào khủng hoảng khi lượng fan sụt giảm. Để cứu vãn tình thế, cô quyết định tổ chức một đám cưới giả, nhưng Hạo Trác lại đột ngột biến mất. Cuộc truy tìm đầy bất ngờ bắt đầu, mở ra những sóng gió mới trong mối quan hệ vốn chỉ là giả tạo.<br>&nbsp;</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1404722', 'season': None, 'voteAverage': 6.2, 'voteCount': 5}, {'id': 'tt35851974', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đi Rồi Sẽ Đến', 'Merrily We Roll Along', 'di-roi-se-den', '<p>Tác phẩm kể về hành trình của Franklin Shepard theo cấu trúc thời gian đảo ngược: từ đỉnh cao thành công ở Hollywood trở về những ngày đầu tại Broadway. Qua từng mảnh ký ức, câu chuyện phơi bày cái giá của tham vọng, những mối quan hệ và lựa chọn đã định hình con người Frank. Phiên bản này là bản ghi hình trực tiếp của vở nhạc kịch Broadway đoạt giải Tony 2024.<br>&nbsp;</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1306400', 'season': None, 'voteAverage': 8.7, 'voteCount': 7}, {'id': 'tt32641442', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Chân Dung Người Nghệ Sĩ', 'Peter Hujar''s Day', 'chan-dung-nguoi-nghe-si', '<p>Một cuộc trò chuyện giữa nhiếp ảnh gia Peter Hujar và người bạn Linda Rosenkrantz vào năm 1974 hé lộ một lát cắt của giới nghệ thuật downtown New York, cùng những đấu tranh cá nhân và khoảnh khắc khai sáng định hình nên cuộc đời của một nghệ sĩ.<br>&nbsp;</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1159539', 'season': None, 'voteAverage': 5, 'voteCount': 5}, {'id': 'tt34250044', 'voteAverage': 6.6, 'voteCount': 303}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Lãng Lãng Nhân Sinh', 'Row to Win', 'lang-lang-nhan-sinh', '<p>Từng một thời hô mưa gọi gió ở thị trấn, “đại ca” Hoàng Vinh Phát nay đã miệng cứng nhưng chân run, bước vào giai đoạn khó khăn của cuộc đời. Thế nhưng, anh cùng gia đình vẫn không để số phận vùi dập. Cậu con trai Hoàng Viễn Đạt bề ngoài tưởng như là người “nhạt nhòa” nhất trong nhà họ Hoàng, nhưng thực chất lại âm thầm toan tính cách làm giàu và “trị cha”. Người vợ Trần Lê Trân thì toàn năng, vượt qua mọi trở ngại, nổi tiếng khắp thị trấn là “mẹ siêu nhân” không dễ động vào. Cô con Hoàng Kiều Kiều liều lĩnh, còn bà cố A Thái lại “thần thông quảng đại”, mỗi người đều tung chiêu riêng mang đến không ít tình huống dở khóc dở cười.<br>&nbsp;</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1516436', 'season': None, 'voteAverage': 9, 'voteCount': 3}, {'id': 'tt37561398', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Tử Cấm: Ngự Miêu Phòng', 'Forbidden City: Imperial Cats', 'tu-cam-ngu-mieu-phong', '<p>Trong Tử Cấm Thành, nơi có lịch sử lâu đời và di sản văn hóa sâu sắc, có rất nhiều chú mèo dễ thương sinh sống. Từ góc nhìn của con người, chúng có một cuộc sống nhàn hạ và đáng ghen tị. Trong số đó, sáu chú mèo hoàng gia là đặc biệt. Chúng có nhiệm vụ bảo vệ ký ức về các di tích văn hóa của "Võ Hoa". Chúng đã nhiều lần tiến vào thế giới Võ Hoa và đánh bại Ác Quỷ Cú Đen, đưa thế giới Võ Hoa trở lại đúng quỹ đạo và bảo vệ các di tích văn hóa. Sáu chú mèo hoàng gia đó là Lư Ban và Momo thuộc tầng lớp văn nhân, và Trang Mai, Aobai, Bình Gan và Tiểu Tỳ thuộc tầng lớp võ nhân. Chúng không chỉ thông minh và dũng cảm mà còn có sự hiểu biết ngầm. Chúng tạo thành Tử Cấm Thành, nơi bảo vệ các bảo vật quốc gia của thế giới.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 11', '16 Tập', 0, false, {'type': 'tv', 'id': '306296', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Tử Xuyên (Phần 2)', 'Purple River (Season 2)', 'tu-xuyen-phan-2-2025', '<p>Truyền kì máu lửa qua từng thời đại: Trong đế quốc của loài người, gia tộc thần bí ở phương Đông xa xôi, Tử Xuyên Tam Kiệt phất lên! Anh cả Đế Lâm chín chắn đa mưu, tàn khốc lí trí, anh hai Sterling chỉ huy một đội quân, có lòng trung thành với nước, em út Tử Xuyên Tú bị người đời gọi với cái tên “Vô Lại”, trí dũng song toàn. Gia tộc Tử Xuyên loạn trong giặc ngoài, Tử Xuyên Tam Kiệt mỗi người đều có thế mạnh riêng: Trong thời khắc nước sôi lửa bỏng, đánh bại Ma tộc hung ác, xông vào hang hổ truy sát tên phản đồ Lôi Hồng đến cùng; Tư Đặc Lâm lấy gia tộc làm gốc, vừa vô tình vừa trọng tình lưu luyến người yêu... Loài người, Ma tộc, Thú tộc. Mỗi tộc ở mỗi phương khác nhau, tranh chấp lẫn nhau trên mảnh đất Đại Lục này, xích mích không ngừng. Khi máu và lửa hòa vào nhau, đao và kiếm va chạm, tạo ra câu chuyện sử thi bi tráng-Tử Xuyên.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 30', '52 Tập', 0, false, {'type': 'tv', 'id': '153869', 'season': 2, 'voteAverage': 8.5, 'voteCount': 2}, {'id': 'tt17048374', 'voteAverage': 0, 'voteCount': 45}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đụng Độ Siêu Trăn', 'Anaconda', 'dung-do-sieu-tran', '<p>Một nhóm bạn thân đang khủng hoảng tuổi trung niên quyết định lên đường vào rừng rậm để làm lại bộ phim yêu thích thời trẻ. Nhưng hành trình hoài niệm nhanh chóng biến thành cuộc chiến sinh tồn dữ dội, khi họ phải đối mặt với thiên tai, rắn khổng lồ, và cả những tên tội phạm nguy hiểm.</p>', 'single', 'completed', 'HD', 'Vietsub', 2025, 0, 'Full', '1', 0, false, {'type': 'movie', 'id': '1234731', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt33244668', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Không Tặc (Phần 2)', 'Hijack (Season 2)', 'khong-tac-phan-2', '<p>In the second season, a Berlin underground train and its commuters are taken hostage, while authorities scramble to save hundreds of lives. Sam Nelson is at the heart of the crisis on board, where one wrong decision could spell disaster.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 3', '8 Tập', 0, false, {'type': 'tv', 'id': '198102', 'season': 2, 'voteAverage': 7.7, 'voteCount': 659}, {'id': 'tt19854762', 'voteAverage': 7.4, 'voteCount': 82344}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Trái Tim Của Yiwha: Tình Yêu Và Báo Thù', 'The Heart of Yiwha: Of Love & Vengeance', 'trai-tim-cua-yiwha-tinh-yeu-va-bao-thu', '<p>Sau khi bọn cướp sát hại cả gia đình, chiến binh trẻ tuổi nọ tìm cách trả thù bằng hắc thuật – nhưng rồi cô con gái quyến rũ của kẻ thù lại khiến hành trình ấy trở nên rối rắm.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 6', '23 Tập', 0, false, {'type': 'tv', 'id': '309206', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Vẻ Đẹp Tái Sinh', 'Beauty Reborn', 've-dep-tai-sinh', '<p>Vừa tốt nghiệp đại học, nhà khoa học mỹ phẩm tham vọng Sara vật lộn với rắc rối gia đình, chuyện đấu đá chốn công sở và mối tình tay ba trong khi cứu công ty mỹ phẩm đang lụn bại.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 16', '18 Tập', 0, false, {'type': 'tv', 'id': '300798', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Sanctuary: Thị Trấn Phù Thủy (Phần 2)', 'Sanctuary: A Witch''s Tale (Season 2)', 'sanctuary-thi-tran-phu-thuy-phan-2', '<p>Một năm sau cuộc săn phù thủy, Sarah và Harper ẩn náu tại Scotland, khi những đạo luật chống phù thủy gieo rắc nỗi sợ và thù hận. Khi Sarah trở lại Sanctuary, một vụ án mạng mới xảy ra khiến căng thẳng leo thang kéo cô vào vòng xoáy xung đột chết chóc, nơi cô phải chiến đấu để bảo vệ con gái và thứ phép thuật đang bị cả thế giới săn đuổi.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 3', '6 Tập', 0, false, {'type': 'tv', 'id': '238585', 'season': 2, 'voteAverage': 6.2, 'voteCount': 27}, {'id': 'tt21632986', 'voteAverage': 6.1, 'voteCount': 1763}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đợi Người GIữa Cửu U', 'Wo Zai Zhe Li Deng Ni', 'doi-nguoi-giua-cuu-u', '<p>Ở Minh Giới, một linh hồn vô tư lự tên là Đồng Phong bất ngờ được lệnh phải hoàn thành việc tu luyện trong vòng ba tháng và chuyển sinh. Hành trình của cô qua các thời đại cổ đại, cộng hòa và hiện đại không chỉ thử thách số phận mà còn hé lộ mối liên hệ đã chôn giấu từ lâu với người cai trị cõi âm, Tuyên Bội.</p>', 'series', 'completed', 'HD', 'Vietsub', 2025, 0, 'Hoàn tất (36/36)', '36 Tập', 0, false, {'type': 'tv', 'id': '273819', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đoàn Tụ ~Sự Thật Thầm Lặng~', 'Silent Truth', 'doan-tu-su-that-tham-lang', '<p>Trở về quê nhà điều tra một vụ án mạng, thám tử nọ phát hiện những mối liên hệ chấn động giữa chính mình với nghi phạm chính và hung khí.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 3', '10 Tập', 0, false, {'type': 'tv', 'id': '306207', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Luật Sư Của Thần Tượng', 'Idol I', 'luat-su-cua-than-tuong', '<p>Luật sư hình sự hàng đầu Maeng Se Na lại âm thầm là fan cứng của một nhóm nhạc nam. Nhưng công việc và đam mê xung đột khi thần tượng cô yêu thích trở thành nghi phạm giết người.</p>', 'series', 'completed', 'HD', 'Vietsub', 2025, 0, 'Hoàn Tất (12/12)', '12 Tập', 0, false, {'type': 'tv', 'id': '307873', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt39068875', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Tìm Mối Tình Đầu Qua Giọng Nói', 'Tune In to the Midnight Heart', 'tim-moi-tinh-dau-qua-giong-noi', '<p>Mỗi khi nằm một mình trong đêm, Arisu Yamabuki luôn tìm thấy sự an ủi từ giọng nói ấm áp của nữ phát thanh viên bí ẩn mang biệt danh “Apollo”. Thế nhưng, một ngày nọ cô đột ngột biến mất khỏi làn sóng radio mà không để lại bất kỳ lời giải thích nào. Nhiều năm sau, khi đã là học sinh lớp 11, Arisu quyết tâm tìm lại Apollo vì vẫn còn những điều chưa kịp nói. Dù không biết diện mạo hay tên thật của cô, cậu lần theo những manh mối dẫn mình đến Câu lạc bộ Phát thanh của trường. Tại đây, Arisu gặp bốn cô gái Rikka, Shinobu, Nene và Iko - những người sở hữu chất giọng giống hệt Apollo và cùng nuôi dưỡng ước mơ trở thành phát thanh viên, mở ra hành trình tìm kiếm giọng nói năm xưa với những rung động tuổi trẻ đầy cảm xúc.</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '24 Tập', 0, false, {'type': 'tv', 'id': '285933', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt38980445', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Peach Lover: Nếm Hương Đào Mọng', 'Peach Lover', 'peach-lover-nem-huong-dao-mong', '<p>Một fan hâm mộ tận tụy giành được cơ hội đóng chung với nhà sáng tạo nội dung người lớn mà anh ta yêu thích, và từ đó, công việc của họ dần phát triển thành một mối quan hệ thực sự.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 2', '10 Tập', 0, false, {'type': 'tv', 'id': '305105', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt39309899', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Có Một Cô Gái Dễ Thương Trong Tổ Đội Anh Hùng, Nên Tôi Thử Tỏ Tình', 'There Was a Cute Girl in the Hero''s Party, so I Tried Confessing to Her', 'co-mot-co-gai-de-thuong-trong-to-doi-anh-hung-nen-toi-thu-to-tinh', '<p>Yoki, một người dân Nhật Bản chuyển sinh thành Ma tộc, hiện đang giữ một vị trí ""làng nhàng"" là thuộc hạ của Ma vương với nhiệm vụ tiêu diệt nhóm Anh hùng. Thế nhưng, khi đối mặt với tổ đội Anh hùng đang tấn công vào lâu đài Ma vương, Yoki bỗng nhiên... ""Thôi xong, đúng gu mình rồi!"" Chuyện không ai ngờ đã xảy ra: anh chàng đã trúng tiếng sét ái tình với Cecilia, nữ tu sĩ của nhóm Anh hùng! Từ khuôn mặt nghiêm túc khi chiến đấu cho đến từng cử chỉ, tất cả đều quá đỗi dễ thương! Đúng chuẩn thiên thần! Thế là Yoki quyết định sẽ tỏ tình, nhưng liệu chuyện gì sẽ xảy ra tiếp theo? Một câu chuyện hài lãng mạn giả tượng thuần khiết nhất dị giới, pha chút phong cách ""hội chứng tuổi teen"" giữa con người và ma tộc chính thức bắt đầu!<br>&nbsp;</p>', 'hoathinh', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '12 Tập', 0, false, {'type': 'tv', 'id': '295366', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt38037498', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Lính Mới (Phần 8)', 'The Rookie (Season 8)', 'linh-moi-phan-8', '<p>The Rookie - Phần 8 tiếp tục theo chân John Nolan và đội LAPD khi họ bước vào một nhiệm vụ chống khủng bố mang tầm quốc tế tại Prague, phối hợp cùng FBI và Interpol. Mùa phim đánh dấu sự trở lại của nhiều nhân vật quen thuộc, đồng thời đẩy mạnh các yếu tố hành động và chiều sâu cảm xúc giữa những tuyến nhân vật. John Nolan (Nathan Fillion) vẫn là trung tâm câu chuyện, vừa làm nhiệm vụ của một cảnh sát, vừa đảm nhận vai trò sĩ quan huấn luyện, cùng các đồng đội đối mặt với những vụ án nguy hiểm, mâu thuẫn nội bộ và thử thách cá nhân. Với chất hài hước đặc trưng kết hợp cùng những pha hành động kịch tính được nâng lên một tầm cao mới, phần phim này chắc chắn là lựa chọn không thể bỏ lỡ đối với người hâm mộ The Rookie.<br>&nbsp;</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 4', '18 Tập', 0, false, {'type': 'tv', 'id': '79744', 'season': 8, 'voteAverage': 8.5, 'voteCount': 2885}, {'id': 'tt7587890', 'voteAverage': 8, 'voteCount': 116400}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Mảnh Đất Độc Thân (Mùa 29)', 'I Am Solo', 'manh-dat-doc-than-mua-29', '<p>Những thăng trầm của việc hẹn hò trở nên thực tế hơn khi những người đàn ông và phụ nữ độc thân bắt đầu hành trình tìm kiếm một người bạn đời xứng đáng để yêu và kết hôn.</p>', 'series', 'completed', 'HD', 'Vietsub', 2021, 0, 'Hoàn tất (10/10)', '10 Tập', 0, false, {'type': 'tv', 'id': '129236', 'season': 1, 'voteAverage': 6, 'voteCount': 2}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Bạn Trai (Phần 2)', 'The Boyfriend (Season 2)', 'ban-trai-phan-2', '<p>Các chàng trai đến ngôi nhà nhỏ ven biển rồi chia sẻ những ấn tượng đầu tiên. Khi tình cảm nảy sinh và một gương mặt mới khiến mọi chuyện nóng lên, một mùa hè khó quên bắt đầu.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 12', '15 Tập', 0, false, {'type': 'tv', 'id': '256220', 'season': 2, 'voteAverage': 8.4, 'voteCount': 15}, {'id': 'tt32551794', 'voteAverage': 7.8, 'voteCount': 1235}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Take That', 'Take That', 'take-that', '<p>Loạt phim tài liệu dùng phim tư liệu chưa từng công bố để kể lại hành trình thăng trầm và màn tái hợp phá kỷ lục của một trong những nhóm nhạc nam huyền thoại nhất Anh quốc.</p>', 'series', 'completed', 'HD', 'Vietsub', 2026, 0, 'Hoàn tất (3/3)', '3 Tập', 0, false, {'type': 'tv', 'id': '262275', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt39049745', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Trước Khi Tình Yêu Bắt Đầu', 'Before Love Begins', 'truoc-khi-tinh-yeu-bat-dau', '<p>Một chương trình truyền hình thực tế hẹn hò quy mô lớn với định dạng hoàn toàn mới "Chương trình hẹn hò tổng hợp 101". Mỗi khách mời nữ cần lắng nghe trái tim mình và tìm ra người duy nhất trong số chín khách mời nam.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2025, 0, 'Tập 18', '20 Tập', 0, false, {'type': 'tv', 'id': '306823', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Địa Ngục Độc Thân (Phần 5)', 'Single''s Inferno (Season 5)', 'dia-nguc-doc-than-phan-5', '<p>It brings the hottest, flirtiest singles to a deserted island, where the only way to escape is to find true romance and spend a romantic night in "paradise".</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2026, 0, 'Tập 7', '12 Tập', 0, false, {'type': 'tv', 'id': '139798', 'season': 5, 'voteAverage': 7.594, 'voteCount': 80}, {'id': 'tt16283666', 'voteAverage': 7.2, 'voteCount': 4014}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Luật Im Lặng (Phần 1)', 'Say Nothing', 'luat-im-lang-phan-1', '<p>Trong lịch sử các cuộc xung đột vũ trang, “Luật Im Lặng” luôn tồn tại như một cơ chế phi chính thức nhưng đầy quyền lực, chi phối hành vi cá nhân và tập thể trong thời chiến. Bộ phim "Say Nothing" (2024) là một bộ phim lịch sử chiến tranh về Bắc Ireland, xoáy mạnh vào vấn đề đó, tập trung vào những hệ lụy của lòng trung thành và sự im lặng. Cái tên "Say Nothing" bắt nguồn từ câu khẩu hiệu của quân đội cộng hòa (IRA): "Whatever you say, say nothing" (Dù bạn nói gì, cũng đừng nói gì cả). Ngoài những cảnh cháy nổ, súng đạn, và đầy mùi hận thù thường thấy trong thời chiến, Say Nothing còn tập trung vào hệ quả của sự lựa chọn. Bộ phim nhận được mưa lời khen từ các chuyên gia phê bình phim về diễn xuất và cách kể chuyện phi tuyến tính dưới góc nhìn đa chiều đầy lôi cuốn, cũng như dựa trên những sự kiện có thật và các cuộc phỏng vấn bí mật chỉ được tiết lộ sau khi các nhân vật qua đời.</p>', 'series', 'ongoing', 'HD', 'Vietsub', 2024, 0, 'Tập 2', '9 Tập', 0, false, {'type': 'tv', 'id': '245256', 'season': 1, 'voteAverage': 7.435, 'voteCount': 92}, {'id': 'tt31122777', 'voteAverage': 8.2, 'voteCount': 15249}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Truy Tìm Dấu Vết', 'Tracks in the Snow', 'truy-tim-dau-vet', '<p>Trò bói toán tà thuật của một người nổi tiếng trên mạng chuyên lừa đảo đã dẫn đến một vụ bắt cóc kỳ quái. Trong vòng 24 giờ, âm mưu chồng chất âm mưu, che giấu những bí mật không thể nói ra. Mối quan hệ giữa ba nhóm nhân vật vật đan xen phức tạp. Trong khoảng thời gian 24 giờ, từng lớp, từng lớp âm mưu vốn ẩn dưới mặt nước tưởng như bình lặng dần được lật mở. Hotgirl mạng xinh đẹp, bọn bắt cóc chợ đen, ông chủ hiệu cầm đồ lần lượt xuất hiện; trên hành trình chạy đua với thời gian, hoặc cứu người, mỗi kẻ đều phô diễn thủ đoạn của mình, dần dần lộ ra những bộ mặt xấu xí.</p>', 'series', 'completed', 'HD', 'Vietsub', 2026, 0, 'Hoàn tất (19/19)', '19 Tập', 0, false, {'type': 'tv', 'id': '310145', 'season': 1, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Chuột Nhí Siêu Tốc Độ', 'Grand Prix of Europe', 'chuot-nhi-sieu-toc-do', '<p>Edda, một chú chuột nhỏ và là con gái của ông chủ hội chợ Erwin, mơ ước trở thành một tay đua xe. Trước thềm kỷ niệm 50 năm Giải đua xe Công thức 1 châu Âu, Edda có cơ hội gặp gỡ thần tượng của mình, ngôi sao đua xe Ed, và giúp cha cô cứu vãn công việc kinh doanh đang trên bờ vực phá sản. Nhưng để làm được điều đó, cô phải tự mình cầm lái.</p>', 'hoathinh', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1316147', 'season': None, 'voteAverage': 7.5, 'voteCount': 31}, {'id': 'tt32897929', 'voteAverage': 5.9, 'voteCount': 654}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Tom & Jerry: Chiến La Bàn Kỳ Bí', 'Tom and Jerry: Forbidden Compass', 'tom-and-jerry-chien-la-ban-ky-bi', '<p>Cặp đôi mèo và chuột huyền thoại vô tình du hành xuyên thời gian trong một bảo tàng. Trên hành trình của mình, họ gặp một nhóm bạn đồng hành mới đầy thú vị và vướng vào một cuộc đối đầu cuối cùng với những thế lực bí ẩn.</p>', 'hoathinh', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1497970', 'season': None, 'voteAverage': 4.3, 'voteCount': 6}, {'id': 'tt37185884', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đồi Câm Lặng: Ác Mộng Trong Sương', 'Return to Silent Hill', 'doi-cam-lang-ac-mong-trong-suong', '<p>Khi James nhận được một bức thư bí ẩn từ Mary — người yêu đã mất của mình — anh bị kéo trở lại Silent Hill, thị trấn quen thuộc một thời nay đã chìm trong bóng tối. Trong hành trình tìm kiếm cô, James phải đối mặt với những sinh vật quái dị và dần hé lộ một sự thật kinh hoàng, thứ sẽ đẩy anh đến bờ vực của sự tỉnh táo.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '680493', 'season': None, 'voteAverage': 5.109, 'voteCount': 47}, {'id': 'tt22868010', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('28 Năm Sau: Ngôi Đền Xương', '28 Years Later: The Bone Temple', '28-nam-sau-ngoi-den-xuong', '<p>Bác sĩ Kelson bất ngờ vướng vào một mối quan hệ mới đầy bất ngờ - với những hậu quả có thể thay đổi thế giới mà họ đang sống - và cuộc chạm trán của Spike với Jimmy Crystal trở thành một cơn ác mộng mà anh không thể thoát khỏi.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1272837', 'season': None, 'voteAverage': 7.2, 'voteCount': 246}, {'id': 'tt32141377', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Bố Già Trở Lại', 'Bố Già Trở Lại', 'bo-gia-tro-lai', '<p>Bộ phim kể về Đằng, một cựu đặc vụ ngầm, người tưởng rằng quá khứ đẫm máu của mình đã lùi lại phía sau, nhưng lại bị buộc phải quay trở lại cuộc chiến khốc liệt khi con gái anh, Yến, đột nhiên bị bắt cóc. Việc giải cứu cô không chỉ trở thành cuộc chiến không khoan nhượng chống lại cái ác tàn nhẫn, mà còn là một hành trình chuộc lỗi và hàn gắn tình cảm sâu sắc, khi Đằng đối mặt với những rạn nứt và mất mát trong chính gia đình mình.</p>', 'single', 'trailer', 'HD', 'Lồng Tiếng', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1621800', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
