INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Giai Điệu Xanh Hy Vọng', 'Song Sung Blue', 'giai-dieu-xanh-hy-vong', '<p>Dựa trên câu chuyện có thật, hai nhạc sĩ sa cơ lập nên một ban nhạc chuyên biểu diễn các ca khúc của Neil Diamond, mang lại niềm vui cho khán giả và cho chính họ. Trên hành trình ấy, họ chứng minh rằng không bao giờ là quá muộn để tìm thấy tình yêu và theo đuổi ước mơ của mình.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1371185', 'season': None, 'voteAverage': 7.605, 'voteCount': 95}, {'id': 'tt30343021', 'voteAverage': 7.5, 'voteCount': 2840}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Nhà Ba Tôi Một Phòng', 'Nhà Ba Tôi Một Phòng', 'nha-ba-toi-mot-phong', '<p>Lấy bối cảnh một khu chung cư cũ với căn nhà chỉ vỏn vẹn một phòng, Nhà Ba Tôi Một Phòng khắc họa mối quan hệ “lệch pha” giữa người cha bảo thủ và cô con gái Gen Z đầy mơ ước. Khi những khác biệt thế hệ va chạm trong không gian chật chội, tình thân dần được thử thách và hàn gắn. Bộ phim mang đến một lát cắt gần gũi về gia đình Việt hiện đại, nơi yêu thương đôi khi bắt đầu từ sự thấu hiểu.</p>', 'single', 'trailer', 'HD', 'Lồng Tiếng', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1607159', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Báu vật trời cho', 'Báu vật trời cho', 'bau-vat-troi-cho', '<p>Khi cậu bé sáu tuổi trong một gia đình đơn thân vô tình tìm được “người cha trời cho” của mình. Hàng loạt bí mật và định mệnh trớ trêu bị lật mở, để rồi mỗi người phải tự hỏi: Điều gì mới thật sự là báu vật trời cho trong đời mình?</p>', 'single', 'trailer', 'HD', 'Lồng Tiếng', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1618321', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
