INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Thỏ Ơi!!', 'Bunnie!', 'tho-oi', '<p>Thỏ Ơi!! là một dự án điện ảnh ra mắt năm 2026 của Trấn Thành. Phim điện ảnh Việt Nam ra mắt vào năm 2026 do Trấn Thành làm đạo diễn.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1528577', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Chiến Nam: Ve Sầu Thoát Xác', 'Chien Nam: The Shedding Cicada', 'chien-nam-ve-sau-thoat-xac', '<p>Khi nhà báo điều tra Ngọc biến mất cùng bằng chứng chống lại tập đoàn Thái Minh Huyền Thoại, một chiếc USB định mệnh rơi vào tay người bạn thân nhất của cô, Kim. Bị một đế chế tội phạm nhắm đến, người bảo vệ duy nhất của Kim là cảnh sát Chiến Nam. Điều bắt đầu như một nhiệm vụ bảo vệ dần biến thành một cuộc thâm nhập sâu vào tổ chức. Khi K52—đồng nghiệp của Chiến Nam—mất tích và Kim bị bắt cóc, Chiến Nam dấn thân vào mạng lưới âm mưu của Thái Minh. Ngay khi công lý dường như trong tầm tay, tên trùm thực hiện kế hoạch “thoát hiểm bằng vỏ ve sầu”. Cuộc chiến thực sự chỉ mới bắt đầu, buộc Chiến Nam phải dấn thân vào những góc tối nhất để khám phá sự thật đằng sau một màn ảo thuật được dàn dựng hoàn hảo.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1621803', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': '', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Vợ lẽ', 'Gundik', 'vo-le', '<p>Một cựu binh nhận việc cướp một ngôi nhà, nhưng hóa ra đó lại là nhà của Nyai, một thê thiếp, tức Gundik.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1318370', 'season': None, 'voteAverage': 5.4, 'voteCount': 4}, {'id': 'tt33022038', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Finnick 2: Quái Xù Tinh Nghịch', 'Finnick 2', 'finnick-2-quai-xu-tinh-nghich', '<p>Finnick vô tình mất khả năng tàng hình, và giờ đây thế giới của những chú lùn đang bị đe dọa. Cùng với người bạn Kristina, anh lên đường tìm kiếm một pháp sư có thể giúp anh lấy lại khả năng tàng hình.</p>', 'hoathinh', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1255369', 'season': None, 'voteAverage': 4, 'voteCount': 2}, {'id': 'tt28779965', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('Đặc Vụ Mật', 'The Secret Agent', 'dac-vu-mat', '<p>Brazil, năm 1977. Marcelo, một chuyên gia công nghệ ngoài bốn mươi tuổi, đang trên đường trốn chạy. Với hy vọng được đoàn tụ cùng con trai, anh đến Recife đúng dịp Carnival—nhưng nhanh chóng nhận ra thành phố này không hề là nơi trú ẩn an toàn như anh tưởng.<br>&nbsp;</p>', 'single', 'trailer', 'HD', 'Vietsub', 2025, 0, 'Trailer', '1', 0, false, {'type': 'movie', 'id': '1220564', 'season': None, 'voteAverage': 7.7, 'voteCount': 219}, {'id': 'tt27847051', 'voteAverage': 8, 'voteCount': 5293}, CURRENT_TIMESTAMP);
INSERT INTO movies (name, origin_name, slug, content, type, status, quality, lang, "year", view, episode_current, episode_total, price, is_free, tmdb_rating, imdb_rating, created_at) VALUES ('"Đồi Gió Hú"', '"Wuthering Heights"', 'doi-gio-hu-2026', '<p>Bi kịch ập đến khi Heathcliff đem lòng yêu Catherine Earnshaw, một phụ nữ xuất thân từ gia đình giàu có ở nước Anh thế kỷ 18.</p>', 'single', 'trailer', 'HD', 'Vietsub', 2026, 0, 'Trailer', '1', 0, true, {'type': 'movie', 'id': '1316092', 'season': None, 'voteAverage': 0, 'voteCount': 0}, {'id': 'tt32897959', 'voteAverage': 0, 'voteCount': 0}, CURRENT_TIMESTAMP);
